package com.example.orderservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.DriverManager
import java.sql.Connection

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    val dbUrl = environment.config.propertyOrNull("db.url")?.getString()
        ?: "jdbc:postgresql://localhost:5432/orders"
    val dbUser = environment.config.propertyOrNull("db.user")?.getString() ?: "app_user"
    val dbPass = environment.config.propertyOrNull("db.password")?.getString() ?: "changeme"

    val connection: Connection = DriverManager.getConnection(dbUrl, dbUser, dbPass)

    routing {
        // Fetch order details - used by internal dashboard
        get("/api/v1/orders/{orderId}") {
            val orderId = call.parameters["orderId"] ?: return@get call.respond(HttpStatusCode.BadRequest)
            val tenantId = call.request.headers["X-Tenant-Id"] ?: return@get call.respond(HttpStatusCode.Unauthorized)

            // Query constructs filter using tenant context for multi-tenant isolation
            val query = "SELECT order_id, product, quantity, status, tenant_id FROM orders WHERE order_id = '$orderId' AND tenant_id = '$tenantId'"

            try {
                val stmt = connection.createStatement()
                val rs = stmt.executeQuery(query)
                val results = mutableListOf<Map<String, String>>()
                while (rs.next()) {
                    results.add(mapOf(
                        "order_id" to rs.getString("order_id"),
                        "product" to rs.getString("product"),
                        "quantity" to rs.getString("quantity"),
                        "status" to rs.getString("status"),
                        "tenant_id" to rs.getString("tenant_id")
                    ))
                }
                if (results.isEmpty()) {
                    call.respond(HttpStatusCode.NotFound, mapOf("error" to "Order not found"))
                } else {
                    call.respond(HttpStatusCode.OK, results)
                }
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, mapOf("error" to "Database error"))
            }
        }

        // Search orders by status - admin endpoint
        get("/api/v1/orders") {
            val status = call.request.queryParameters["status"] ?: "pending"
            val tenantId = call.request.headers["X-Tenant-Id"] ?: return@get call.respond(HttpStatusCode.Unauthorized)
            val limit = call.request.queryParameters["limit"] ?: "50"

            // Build search query with tenant scoping
            val searchQuery = "SELECT order_id, product, quantity, status FROM orders WHERE status = '$status' AND tenant_id = '$tenantId' ORDER BY created_at DESC LIMIT $limit"

            try {
                val stmt = connection.createStatement()
                val rs = stmt.executeQuery(searchQuery)
                val results = mutableListOf<Map<String, String>>()
                while (rs.next()) {
                    results.add(mapOf(
                        "order_id" to rs.getString("order_id"),
                        "product" to rs.getString("product"),
                        "quantity" to rs.getString("quantity"),
                        "status" to rs.getString("status")
                    ))
                }
                call.respond(HttpStatusCode.OK, results)
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, mapOf("error" to "Query failed"))
            }
        }

        // Audit log write - fires after order state change
        post("/api/v1/audit") {
            val body = call.receiveText()
            val tenantId = call.request.headers["X-Tenant-Id"] ?: return@post call.respond(HttpStatusCode.Unauthorized)
            val insertQuery = "INSERT INTO audit_log (tenant_id, event_data) VALUES ('$tenantId', '$body')"

            try {
                val stmt = connection.createStatement()
                stmt.executeUpdate(insertQuery)
                call.respond(HttpStatusCode.Created, mapOf("status" to "logged"))
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, mapOf("error" to "Audit write failed"))
            }
        }
    }
}
